import fs from 'node:fs';

const options = JSON.parse(fs.readFileSync(new URL('./provider-options.json', import.meta.url), 'utf8'));

export const apiVersion = 1;

export function generate(context) {
  fs.appendFileSync(options.logPath, 'sdk,');
  if (!fs.existsSync(context.input)) throw new Error('controller output was not generated');
  fs.mkdirSync(context.output, { recursive: true });
  const content = '/* Generated by @exprtlabs/golem-openapi-ts. Do not edit. */\n';
  return {
    apiVersion: 1,
    artifacts: [{ path: context.output + '/index.ts', content }],
    manifestPaths: [],
    watchInputs: [context.input],
  };
}
